validator:
function validate(input) {
  const [{ Courses = [] }] = input;
  const seen = new Set();
  for (const [student, cls] of Courses) {
    if (student === null || cls === null) return 'Every row needs a student and a class.';
    const key = JSON.stringify([String(student).toLowerCase(), String(cls).toLowerCase()]);
    if (seen.has(key)) return `${student} is enrolled in ${cls} twice.`;
    seen.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const classes = small ? ['Math', 'Art', 'Biology'] : Array.from({ length: 250 }, (_, i) => `Class${i + 1}`);
  const students = small ? ['A', 'B', 'C', 'D', 'E', 'F', 'G'] : Array.from({ length: 400 }, (_, i) => `S${i + 1}`);
  const Courses = [];
  for (const cls of classes) {
    // Class sizes cluster around the threshold of 5.
    const want = small ? Math.floor(rand() * 7) : Math.floor(rand() * 13);
    const pool = students.slice();
    for (let k = 0; k < want && pool.length; k++) {
      if (small && Courses.length >= 8) break;
      const [student] = pool.splice(Math.floor(rand() * pool.length), 1);
      Courses.push([student, cls]);
    }
  }
  // Interleave the classes so rows are not grouped by class.
  for (let i = Courses.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [Courses[i], Courses[j]] = [Courses[j], Courses[i]]; }
  return [{ Courses }];
}
